/// BRISQUE 预训练模型参数（LIVE 语料上训练的 epsilon-SVR，RBF 核，
/// gamma=0.05）：特征归一化 min/max（缩放到 [-1,1]）、支持向量与
/// 系数、rho。来源：rehanguha/brisque 的 models/svm.txt +
/// normalize.pickle（官方 LIVE 发布的 allmodel/allrange 同款）。
/// 浮点数组以 base64 编码的小端 float64 存储（运行时用
/// decodeB64F64 解码一次）。由 scratch/brisque_svm.txt 等经脚本
/// 生成，勿手改。
library;

import 'dart:convert';
import 'dart:typed_data';

/// base64 小端 float64 → Float64List。
Float64List decodeB64F64(String s) =>
    Float64List.view(Uint8List.fromList(base64.decode(s)).buffer);

/// SVM RBF 核 gamma。
const brisqueSvmGamma = 0.05;

/// SVM 决策函数偏置 rho（预测值 = Σ coef·K(x,sv) - rho）。
const brisqueSvmRho = -155.845;

/// 特征归一化下限（36 维）。
final brisqueFeatureMin = decodeB64F64('');

/// 特征归一化上限（36 维）。
final brisqueFeatureMax = decodeB64F64('');

/// SVM 支持向量系数（770 个）。
final brisqueSvCoef = decodeB64F64('');

/// SVM 支持向量（770×36，行优先扁平化）。
final brisqueSupportVectors = decodeB64F64('');

/// 支持向量个数。
const brisqueSvCount = 770;
